begin;
create or replace function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end;$$;
do $$
declare org uuid:=gen_random_uuid();actor uuid:='99999999-9999-4999-8999-999999999902';conversation uuid:=gen_random_uuid();brief uuid:=gen_random_uuid();version uuid:=gen_random_uuid();connection uuid:=gen_random_uuid();op uuid:=gen_random_uuid();request jsonb;prepared jsonb;quote jsonb;rate jsonb;acceptance jsonb;job jsonb;again jsonb;manifest jsonb;source jsonb;video_request jsonb;
begin
 insert into public.organizations(id,name,slug) values(org,'Transactional Design media QA','design-media-qa-'||org::text);
 insert into public.organization_memberships(organization_id,user_id,role,department_id,status) values(org,actor,'operations_admin','design','active');
 insert into public.department_chat_conversations(id,organization_id,department_id,owner_id,title,context_kind) values(conversation,org,'design',actor,'Rollback media QA','department_private');
 insert into public.design_creative_briefs(id,organization_id,visibility,created_by,updated_by) values(brief,org,'private',actor,actor);
 insert into public.design_creative_brief_versions(id,organization_id,creative_brief_id,version_number,content,content_checksum,validation_snapshot,operation_key,created_by) values(version,org,brief,1,'{"title":"Synthetic","purpose":"Test","instructions":"Synthetic local-only image","audience":"QA"}',repeat('a',64),'{"valid":true}',gen_random_uuid(),actor);
 update public.design_creative_briefs set current_version_id=version,frozen_version_id=version,revision=2 where id=brief;
 insert into public.integration_connections(id,organization_id,provider,display_name,secret_name,status,created_by) values(connection,org,'higgsfield','Rollback no-credential fixture','ANKA_HIGGSFIELD_LOCAL_QA_NO_CREDENTIAL','verified',actor);
 insert into private.ai_execution_budget_limits(organization_id,monthly_limit_microusd,spend_guard_mode) values(org,3000000,'local_monthly_cap');
 request:=jsonb_build_object('organization_id',org,'context',jsonb_build_object('kind','private','id',conversation),'creative_brief_version_id',version,'connector_connection_id',connection,'provider','higgsfield','model_id','higgsfield-ai/soul/v2/standard','settings','{"resolution":"720p","aspect_ratio":"16:9","enhance_prompt":false}'::jsonb,'output_count',4,'input_versions','[]'::jsonb,'prompt_checksum',repeat('0',64));
 prepared:=public.prepare_design_media_request(org,actor,request);request:=prepared->'request';
 perform pg_temp.ok(request->>'prompt_checksum'=encode(sha256(convert_to(prepared->>'prompt','UTF8')),'hex'),'database derives exact confirmed prompt');
 rate:=public.configure_design_media_rate(org,actor,'higgsfield',request->>'model_id',request->'settings',600000,'https://open.higgsfield.ai/pricing#synthetic',clock_timestamp(),clock_timestamp()+interval '1 hour');
 quote:=public.quote_design_media_request(org,actor,request);acceptance:=jsonb_build_object('generate',true,'quote_id',quote->>'id','request_checksum',quote->>'request_checksum','total_max_charge_microusd',2400000);
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL missing confirmation dispatched';exception when insufficient_privilege then raise notice 'PASS over-threshold dispatch blocks without confirmation';end;
 perform pg_temp.ok((select count(*)=0 from private.ai_execution_budget_reservations where organization_id=org),'failed acceptance reserves no spend');
 job:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance||'{"confirm_above_threshold":true}'::jsonb);
 perform pg_temp.ok(not (job->>'must_not_submit')::boolean and job->>'claim_id' is not null,'first exact request gets one durable dispatch claim');
 again:=public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance||'{"confirm_above_threshold":true}'::jsonb);
 perform pg_temp.ok((again->>'must_not_submit')::boolean and again->>'id'=job->>'id','replay cannot dispatch again');
 perform pg_temp.ok((select count(*)=1 and sum(max_cost_microusd)=2400000 from private.ai_execution_budget_reservations where organization_id=org),'shared ledger holds exact complete request once');
 begin perform public.claim_design_media_generation(org,actor,gen_random_uuid(),(quote->>'id')::uuid,request,prepared->>'prompt',acceptance||'{"confirm_above_threshold":true}'::jsonb);raise exception 'FAIL monthly cap bypassed';exception when numeric_value_out_of_range then raise notice 'PASS second request respects shared monthly cap';end;
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,'Changed prompt',acceptance);raise exception 'FAIL prompt substituted';exception when invalid_parameter_value then raise notice 'PASS changed prompt cannot dispatch';end;
 begin perform public.prepare_design_media_request(org,actor,request||jsonb_build_object('settings',request->'settings'||'{"webhook":"https://outside"}'::jsonb));raise exception 'FAIL unknown setting accepted';exception when invalid_parameter_value then raise notice 'PASS unknown provider setting rejected';end;
 perform public.record_design_media_generation(org,actor,(job->>'id')::uuid,(job->>'claim_id')::uuid,'provider_completed','{"requestId":"local-synthetic-original","state":"provider_completed"}');
 select jsonb_agg(jsonb_build_object('id',(job->>'id')||':'||i,'bucket','design-generated-media','path',org::text||'/private/'||actor::text||'/media/'||(job->>'id')||'/'||i||'.png','extension','png','mime_type','image/png','checksum',repeat('c',64),'byte_length',12) order by i) into manifest from generate_series(0,3) i;
 -- Canonical private bucket prerequisite, transaction-only; existing buckets remain unchanged.
 insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('design-generated-media','design-generated-media',false,10485760,array['image/png']::text[]) on conflict(id) do nothing;
 insert into storage.objects(bucket_id,name,metadata) select 'design-generated-media',value->>'path','{"size":12,"mimetype":"image/png"}'::jsonb from jsonb_array_elements(manifest);
 again:=public.complete_design_media_storage(org,actor,(job->>'id')::uuid,(job->>'claim_id')::uuid,manifest);
 perform pg_temp.ok(again->>'status'='ready','complete exact original manifest retained');
 source:=public.resolve_design_media_input(org,actor,request->'context',(job->>'id')||':0',repeat('c',64));
 perform pg_temp.ok(source->>'checksum'=repeat('c',64),'same-context immutable original can be selected');
 begin perform public.resolve_design_media_input(org,actor,request->'context',(job->>'id')||':0',repeat('d',64));raise exception 'FAIL changed original accepted';exception when insufficient_privilege then raise notice 'PASS changed original checksum denied';end;
 begin perform public.resolve_design_media_input(org,actor,jsonb_build_object('kind','private','id',gen_random_uuid()),(job->>'id')||':0',repeat('c',64));raise exception 'FAIL source context escaped';exception when insufficient_privilege then raise notice 'PASS original cannot cross conversation';end;
 source:=jsonb_build_object('kind','media_output','id',(job->>'id')||':0','checksum',repeat('c',64),'provider_consent',jsonb_build_object('provider','higgsfield','source_id',(job->>'id')||':0','checksum',repeat('c',64),'allow_transfer',true));
 video_request:=request||jsonb_build_object('model_id','bytedance/seedance-2.5/image-to-video','output_count',1,'settings','{"duration_seconds":5,"resolution":"720p","output_format":"mp4","generate_audio":false}'::jsonb,'input_versions',jsonb_build_array(source));
 perform public.prepare_design_media_request(org,actor,video_request);raise notice 'PASS exact original and provider consent prepare animation';
 begin perform public.prepare_design_media_request(org,actor,jsonb_set(video_request,'{input_versions,0,provider_consent,allow_transfer}','false'));raise exception 'FAIL missing transfer consent accepted';exception when insufficient_privilege then raise notice 'PASS input transfer without consent denied';end;
 begin perform public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,2400001,'Synthetic rollback billing evidence');raise exception 'FAIL settlement exceeded bound';exception when numeric_value_out_of_range then raise notice 'PASS settlement cannot exceed reservation';end;
 again:=public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,1200000,'Synthetic rollback billing evidence');
 perform pg_temp.ok(again->>'status'='settled' and not (again->>'idempotent_replay')::boolean,'verified bill settles existing shared reservation');
 again:=public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,1200000,'Synthetic rollback billing evidence');
 perform pg_temp.ok((again->>'idempotent_replay')::boolean,'same settlement replay is stable');
 perform pg_temp.ok((select count(*)=1 from private.ai_execution_budget_events e join private.ai_execution_budget_reservations r on r.id=e.reservation_id where r.design_media_job_id=(job->>'id')::uuid and e.transition='settled'),'settlement replay produces no duplicate accounting event');
 begin perform public.reconcile_design_media_budget(org,(job->>'id')::uuid,actor,(job->>'claim_id')::uuid,1000000,'Different evidence');raise exception 'FAIL changed bill accepted';exception when unique_violation then raise notice 'PASS conflicting settlement rejected';end;
 perform pg_temp.ok(not has_function_privilege('authenticated','public.reconcile_design_media_budget(uuid,uuid,uuid,uuid,bigint,text)','execute'),'billing reconciliation is not a caller-controlled public action');
 update public.integration_connections set status='disabled' where id=connection;
 begin perform public.claim_design_media_generation(org,actor,op,(quote->>'id')::uuid,request,prepared->>'prompt',acceptance);raise exception 'FAIL revoked connector allowed';exception when insufficient_privilege then raise notice 'PASS revoked connector blocks dispatch replay';end;
 again:=public.get_design_media_generation(org,actor,op);perform pg_temp.ok(again->>'id'=job->>'id','read-only original recovery remains available without provider resubmission');
 perform pg_temp.ok(jsonb_array_length(public.list_design_media_generations(org,actor,request->'context'))=1,'history discovers original request without browser identity');
 perform pg_temp.ok(not ((public.list_design_media_generations(org,actor,request->'context')->0) ?| array['claim_id','provider_receipt','prompt','output_manifest']),'history omits dispatch and provider internals');
 begin perform public.list_design_media_generations(org,actor,jsonb_build_object('kind','private','id',gen_random_uuid()));raise exception 'FAIL foreign history accepted';exception when insufficient_privilege then raise notice 'PASS foreign conversation history denied';end;
 perform pg_temp.ok(not has_function_privilege('authenticated','public.list_design_media_generations(uuid,uuid,jsonb,timestamptz,uuid)','execute'),'history cannot spoof actor directly');
 update public.organization_memberships set status='revoked' where organization_id=org and user_id=actor;
 begin perform public.get_design_media_generation(org,actor,op);raise exception 'FAIL revoked actor reads';exception when insufficient_privilege then raise notice 'PASS revoked actor cannot recover';end;
 begin perform public.list_design_media_generations(org,actor,request->'context');raise exception 'FAIL revoked history accepted';exception when insufficient_privilege then raise notice 'PASS revoked actor cannot discover history';end;
 perform pg_temp.ok(not has_function_privilege('authenticated','public.claim_design_media_generation(uuid,uuid,uuid,uuid,jsonb,text,jsonb)','execute'),'no direct actor spoof at dispatch');
 perform pg_temp.ok(not has_table_privilege('service_role','private.design_media_generation_jobs','insert,update,delete'),'job writes only through checked functions');
end;$$;
rollback;
